// profile-switcher tests: switch-time tier sync (tiers.ts).
//
// A tier-managed profile's overlay is GENERATED by scripts/tiers-sync.mjs, so
// the RPC set path regenerates it from the authored tiers before anything is
// persisted or applied. These tests exercise the helper against a temp
// CONFIG_DIR layout (agents/, profiles/, scripts/):
//   1. success regenerates the overlay and reports it; authored descriptions
//      survive; a second run is a no-op
//   2. an invalid tiers.json is refused with the validator's message and the
//      existing overlay is left byte-identical (the switch never applies it)
//   3. a profile with no tiers.json (legacy hand-written overlay) is a no-op
//   4. a plain launch regenerates a stale overlay BEFORE the initial apply
//   5. a failed launch sync logs a warning and still applies the existing
//      overlay (the plugin cannot abort the launch)
//   6. an OPENCODE_CONFIG launch skips the sync (its overlay is already merged)
//
// Run: node --test plugin-src/profile-switcher/test/

import { test, after } from "node:test";
import assert from "node:assert/strict";
import {
  copyFileSync,
  existsSync,
  mkdirSync,
  mkdtempSync,
  readFileSync,
  rmSync,
  writeFileSync,
} from "node:fs";
import os from "node:os";
import path from "node:path";
import { fileURLToPath } from "node:url";

import { syncLaunchTierOverlay, syncProfileTiers } from "../tiers.ts";

const HERE = path.dirname(fileURLToPath(import.meta.url));
const REPO_ROOT = path.resolve(HERE, "..", "..", "..");
const TMP_BASE = existsSync("/tmp/opencode") ? "/tmp/opencode" : os.tmpdir();

const tiers = [];
after(() => {
  for (const root of tiers) {
    try {
      rmSync(root, { recursive: true, force: true });
    } catch {
      // best effort
    }
  }
});

const AGENT_FILES = ["orchestrator", "sidekick", "analyst", "reviewer"];

const TIERS = {
  tiers: {
    big: { model: "test-provider/big-model#max", description: "hard reasoning" },
    medium: { model: "test-provider/medium-model", description: "default work" },
    small: { model: "test-provider/small-model", description: "mechanical edits" },
  },
  agents: {
    orchestrator: "big",
    sidekick: "medium",
    analyst: "medium",
    reviewer: "medium",
    title: "small",
    compaction: "small",
  },
};

// A minimal CONFIG_DIR: the real tiers-sync script, the agents it validates
// against, and one profile directory.
function makeRoot(profile = "demo") {
  const root = mkdtempSync(path.join(TMP_BASE, "profile-switcher-tiers-test-"));
  tiers.push(root);
  mkdirSync(path.join(root, "agents"), { recursive: true });
  mkdirSync(path.join(root, "profiles", profile), { recursive: true });
  mkdirSync(path.join(root, "scripts"), { recursive: true });
  copyFileSync(
    path.join(REPO_ROOT, "scripts", "tiers-sync.mjs"),
    path.join(root, "scripts", "tiers-sync.mjs")
  );
  for (const name of AGENT_FILES) {
    writeFileSync(path.join(root, "agents", `${name}.md`), "---\nmode: subagent\n---\n");
  }
  return root;
}

function writeTiers(root, profile, data) {
  writeFileSync(
    path.join(root, "profiles", profile, "tiers.json"),
    JSON.stringify(data, null, 2) + "\n"
  );
}

function overlayPath(root, profile = "demo") {
  return path.join(root, "profiles", profile, "opencode.jsonc");
}

test("a tier-managed switch regenerates the overlay from tiers.json", async () => {
  const root = makeRoot();
  writeTiers(root, "demo", TIERS);
  const first = await syncProfileTiers({ configDir: root, profile: "demo" });
  assert.equal(first.ok, true, first.output);
  assert.match(first.output, /profiles\/demo\/opencode\.jsonc regenerated/);

  const text = readFileSync(overlayPath(root), "utf8");
  const config = JSON.parse(text.replace(/^\/\/[^\n]*\n/, ""));
  assert.equal(config.agents.orchestrator.model, "test-provider/big-model#max");
  assert.equal(config.agents.sidekick.model, "test-provider/medium-model");
  assert.equal(config.agents.reviewer.model, "test-provider/medium-model");
  assert.equal(config.agents.compaction.model, "test-provider/small-model");
  assert.equal(config.small_model, "test-provider/small-model");

  // The authored mapping is untouched: descriptions stay, models stay.
  const data = JSON.parse(
    readFileSync(path.join(root, "profiles", "demo", "tiers.json"), "utf8")
  );
  assert.equal(data.tiers.big.description, "hard reasoning");
  assert.equal(data.tiers.vision, undefined);

  const second = await syncProfileTiers({ configDir: root, profile: "demo" });
  assert.equal(second.ok, true, second.output);
  assert.match(second.output, /up to date/);
  assert.equal(readFileSync(overlayPath(root), "utf8"), text);
});

test("an invalid tiers.json refuses the switch and leaves the overlay untouched", async () => {
  const root = makeRoot();
  const broken = structuredClone(TIERS);
  broken.tiers.big.model = "no-slash";
  writeTiers(root, "demo", broken);
  const stale = "// hand written stale overlay\n";
  writeFileSync(overlayPath(root), stale);

  const result = await syncProfileTiers({ configDir: root, profile: "demo" });
  assert.equal(result.ok, false);
  assert.match(
    result.output,
    /tier "big" model "no-slash" is not <provider>\/<model>\[#variant\]/
  );
  assert.equal(readFileSync(overlayPath(root), "utf8"), stale);
});

test("a profile with no tiers.json is a no-op (legacy overlay)", async () => {
  const root = makeRoot();
  const overlay = "{\n  \"$schema\": \"https://opencode.ai/config.json\"\n}\n";
  writeFileSync(overlayPath(root), overlay);

  const result = await syncProfileTiers({ configDir: root, profile: "demo" });
  assert.equal(result.ok, true);
  assert.equal(result.output, "");
  assert.equal(readFileSync(overlayPath(root), "utf8"), overlay);
});

test("a plain launch regenerates a stale overlay before the initial apply", async () => {
  const root = makeRoot();
  writeTiers(root, "demo", TIERS);
  writeFileSync(overlayPath(root), "// stale overlay from a hand-edited tiers.json\n");
  const logs = [];
  let applied = null;

  await syncLaunchTierOverlay(
    {
      configDir: root,
      profile: "demo",
      launchSuppressed: false,
      log: (level, message, extra) => logs.push({ level, message, extra }),
    },
    async () => {
      applied = readFileSync(overlayPath(root), "utf8");
    }
  );

  assert.deepEqual(logs, []);
  assert.ok(applied, "the initial apply still ran");
  assert.match(applied, /GENERATED/);
  assert.equal(
    JSON.parse(applied.replace(/^\/\/[^\n]*\n/, "")).agents.sidekick.model,
    "test-provider/medium-model"
  );
});

test("a failed launch sync logs and still applies the existing overlay", async () => {
  const root = makeRoot();
  const broken = structuredClone(TIERS);
  broken.tiers.big.model = "no-slash";
  writeTiers(root, "demo", broken);
  const stale = "// hand written stale overlay\n";
  writeFileSync(overlayPath(root), stale);
  const logs = [];
  let applied = null;

  await syncLaunchTierOverlay(
    {
      configDir: root,
      profile: "demo",
      launchSuppressed: false,
      log: (level, message, extra) => logs.push({ level, message, extra }),
    },
    async () => {
      applied = readFileSync(overlayPath(root), "utf8");
    }
  );

  assert.equal(logs.length, 1);
  assert.equal(logs[0].level, "warn");
  assert.equal(logs[0].extra.profile, "demo");
  assert.match(
    logs[0].extra.output,
    /tier "big" model "no-slash" is not <provider>\/<model>\[#variant\]/
  );
  assert.equal(applied, stale);
  assert.equal(readFileSync(overlayPath(root), "utf8"), stale);
});

test("an OPENCODE_CONFIG launch skips the sync", async () => {
  const root = makeRoot();
  writeTiers(root, "demo", TIERS);
  const stale = "// overlay already merged by the launch\n";
  writeFileSync(overlayPath(root), stale);
  let applied = null;

  await syncLaunchTierOverlay(
    {
      configDir: root,
      profile: "demo",
      launchSuppressed: true,
      log: () => assert.fail("a suppressed launch must not log"),
    },
    async () => {
      applied = readFileSync(overlayPath(root), "utf8");
    }
  );

  assert.equal(applied, stale);
  assert.equal(readFileSync(overlayPath(root), "utf8"), stale);
});
